def clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return low
    return value

def paginate(items, page, size):
    start = page * size
    return items[start:start + size]

def parse_count(raw, default):
    try:
        return int(raw) or default
    except (ValueError, TypeError):
        return default

def without(items, target):
    result = list(items)
    for value in result:
        if value == target:
            result.remove(value)
    return result

def retry_delay(raw, default):
    try:
        return int(raw)
    except (ValueError, TypeError):
        return default
